import{_ as a,o as e,c as l,a0 as n}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"String.prototype.slice()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/String/slice.md","filePath":"jsApi/String/slice.md","lastUpdated":1791573371000}'),t={name:"jsApi/String/slice.md"};function o(p,s,r,i,c,d){return e(),l("div",null,[...s[0]||(s[0]=[n(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/String/slice" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/slice" target="_blank">en</a></p><h1 id="string-prototype-slice" tabindex="-1">String.prototype.slice() <a class="header-anchor" href="#string-prototype-slice" aria-label="Permalink to &quot;String.prototype.slice()&quot;">​</a></h1><p>slice() 方法提取一个字符串的一部分，并返回一新的字符串。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">str.</span><span style="color:#6F42C1;">slice</span><span style="color:#24292E;">(beginSlice[, endSlice])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>beginSlice</code> 从该索引（以 0 为基数）处开始提取原字符串中的字符。如果值为负数，会被当做 sourceLength + beginSlice 看待， 这里的sourceLength 是字符串的长度 (例如， 如果beginSlice 是 -3 则看作是: sourceLength - 3)</li><li><code>endSlice 可选</code> 在该索引（以 0 为基数）处结束提取字符串。如果省略该参数，slice会一直提取到字符串末尾。如果该参数为负数， 则被看作是 sourceLength + endSlice，这里的 sourceLength 就是字符串的长度(例如，如果 endSlice 是 -3，则是, sourceLength - 3)。</li></ul><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>slice() 从一个字符串中提取字符串并返回新字符串。在一个字符串中的改变不会影响另一个字符串。也就是说，slice 不修改原字符串， 只会返回一个包含了原字符串中部分字符的新字符串。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>注意：slice() 提取的新字符串包括beginSlice但不包括 endSlice。</p></div><p>例1：str.slice(1, 4) 提取新字符串从第二个字符到第四个 (字符索引值为 1, 2, 和 3)。</p><p>例2：str.slice(2, -1) 提取第三个字符到倒数第二个字符。</p><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><h3 id="使用-slice-创建一个新的字符串" tabindex="-1">使用 slice() 创建一个新的字符串 <a class="header-anchor" href="#使用-slice-创建一个新的字符串" aria-label="Permalink to &quot;使用 slice() 创建一个新的字符串&quot;">​</a></h3><p>下面例子使用 slice() 来创建新字符串:</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> str1 </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;The morning is upon us.&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> str2 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> str1.</span><span style="color:#6F42C1;">slice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">4</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(str2); </span><span style="color:#6A737D;">// OUTPUT: morning is upon u</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="给-slice-传入负值索引" tabindex="-1">给 slice() 传入负值索引 <a class="header-anchor" href="#给-slice-传入负值索引" aria-label="Permalink to &quot;给 slice() 传入负值索引&quot;">​</a></h3><p>下面的例子在 slice() 使用了负值索引:</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> str </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;The morning is upon us.&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">str.</span><span style="color:#6F42C1;">slice</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">);     </span><span style="color:#6A737D;">// returns &#39;us.&#39;</span></span>
<span class="line"><span style="color:#24292E;">str.</span><span style="color:#6F42C1;">slice</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// returns &#39;us&#39;</span></span>
<span class="line"><span style="color:#24292E;">str.</span><span style="color:#6F42C1;">slice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">);  </span><span style="color:#6A737D;">// returns &#39;The morning is upon us&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 3rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,21)])])}const u=a(t,[["render",o]]);export{h as __pageData,u as default};
